const upsertRouteIntent = `-- name: UpsertRouteIntent :one
INSERT INTO public_route_publications(publisher_id, hostname, resource_id, environment_id, cluster_ids, withdrawing, change_sequence)
VALUES ($1, $2, $3, $4, $5, $6, $7)
ON CONFLICT (hostname) DO UPDATE SET resource_id = EXCLUDED.resource_id, environment_id = EXCLUDED.environment_id, cluster_ids = EXCLUDED.cluster_ids,
 withdrawing = EXCLUDED.withdrawing, revision = public_route_publications.revision + 1,
 change_sequence = EXCLUDED.change_sequence, message = '', updated_at = NOW()
WHERE public_route_publications.resource_id = EXCLUDED.resource_id
 AND public_route_publications.environment_id = EXCLUDED.environment_id
 OR (public_route_publications.withdrawing AND public_route_publications.acknowledged_revision = public_route_publications.revision
 AND public_route_publications.drain_until <= NOW())
RETURNING id, publisher_id, hostname, resource_id, environment_id, cluster_ids, withdrawing, revision, change_sequence, acknowledged_revision, acknowledged_at, drain_until, message, updated_at
`

type UpsertRouteIntentParams struct {
	PublisherID    uuid.UUID   `json:"publisherId"`
	Hostname       string      `json:"hostname"`
	ResourceID     uuid.UUID   `json:"resourceId"`
	EnvironmentID  uuid.UUID   `json:"environmentId"`
	ClusterIds     []uuid.UUID `json:"clusterIds"`
	Withdrawing    bool        `json:"withdrawing"`
	ChangeSequence int64       `json:"changeSequence"`
}

func (q *Queries) UpsertRouteIntent(ctx context.Context, arg UpsertRouteIntentParams) (PublicRoutePublication, error) {
	row := q.db.QueryRow(ctx, upsertRouteIntent,
		arg.PublisherID,
		arg.Hostname,
		arg.ResourceID,
		arg.EnvironmentID,
		arg.ClusterIds,
		arg.Withdrawing,
		arg.ChangeSequence,
	)
	var i PublicRoutePublication
	err := row.Scan(
		&i.ID,
		&i.PublisherID,
		&i.Hostname,
		&i.ResourceID,
		&i.EnvironmentID,
		&i.ClusterIds,
		&i.Withdrawing,
		&i.Revision,
		&i.ChangeSequence,
		&i.AcknowledgedRevision,
		&i.AcknowledgedAt,
		&i.DrainUntil,
		&i.Message,
		&i.UpdatedAt,
	)
	return i, err
}
